#!/usr/bin/env bash
# G1 PARITY - the pre-change binary and the chi binary over the SAME window
# set on the 10 GB full-stack container: every row byte-identical, forced
# rows equal to the old path's single-pair histograms, and the opt-in v4
# row file decoding back to exactly the same rows.
#
#   usage: chi_g1_parity.sh XSA XSA_OLD CONTAINER CORPUS MAP WORKDIR [JOBS]
#
# The window set is generated by gates/chi_gen_windows.c (doc-contained,
# base = the TRUE document start from the map): ramp windows at document
# starts (empty/short/full spines), mid-document windows, END-adjacent tail
# windows, short-left windows, and windows around INTERNAL 0x1E bytes (the
# ENUM layer) found by scanning the corpus. Every step prints N of things
# examined; a vacuous check fails the gate.
set -uo pipefail
HERE=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
XSA=${1:?new xsa}
XSA_OLD=${2:?pre-change xsa}
CONTAINER=${3:?10G container}
CORPUS=${4:?10G corpus}
MAP=${5:?map dir with seps.bin}
WORK=${6:?work dir}
JOBS=${7:-16}
PATIENCE=${PATIENCE:-14400}
mkdir -p "$WORK"

fail() { echo "GATE_FAIL: $*"; exit 1; }
no_survivors() {
  local pids
  pids=$(pgrep -f "xsa consult --container $CONTAINER" 2>/dev/null || true)
  if [ -n "$pids" ]; then
    for p in $pids; do
      tr '\0' ' ' < "/proc/$p/cmdline" 2>/dev/null | grep -qF "$WORK" && \
        fail "SURVIVOR pid=$p"
    done
  fi
  echo "NO_SURVIVORS work=$WORK"
}
run() { # tag out extra...
  local tag=$1 out=$2; shift 2
  rm -f "$out" "$out.journal"
  setsid timeout --kill-after=10 "$PATIENCE" \
    "$XSA" consult --container "$CONTAINER" --corpus "$CORPUS" \
      --windows "$WORK/windows.jsonl" --output "$out" \
      --rss-gb 16 -j "$JOBS" "$@"
  local rc=$?
  no_survivors
  [ $rc -eq 0 ] || fail "run $tag exited $rc (journal tail below)"
  return 0
}

[ -f "$CONTAINER" ] || fail "container $CONTAINER is missing (build it first: xsa build --tape ...)"
[ -f "$MAP/seps.bin" ] || fail "map $MAP/seps.bin is missing"
"$XSA" trie-info "$CONTAINER" 2>/dev/null | head -3 || true

echo "=== G1: the window set (doc-contained, from the map)"
"$XSA" docstarts info "$CONTAINER" 2>&1 | head -5 || true
gcc -O2 -o "$WORK/chi_gen_windows" "$HERE/chi_gen_windows.c" || fail "gen_windows build"
"$WORK/chi_gen_windows" "$MAP/seps.bin" "$CORPUS" "$WORK/windows.jsonl" 240 9127 \
  | tee "$WORK/windows.log" || fail "window generation"
WINS=$(wc -l < "$WORK/windows.jsonl")
[ "$WINS" -gt 100 ] || fail "vacuous window set: $WINS windows"

echo "=== G1a: the PRE-CHANGE binary over the set"
run old "$WORK/old.rows" --boundary-cap 8192

echo "=== G1b: the chi binary over the same set (default v3 output)"
run new "$WORK/new.rows" --boundary-cap 8192

echo "=== G1c: the opt-in v4 row file over the same set"
run v4 "$WORK/v4.rows" --boundary-cap 8192 --rows-v4

echo "=== G1d: byte identity, old vs new"
if cmp -s "$WORK/old.rows" "$WORK/new.rows"; then
  echo "G1_BYTE_IDENTICAL old_vs_new=1 bytes=$(stat -c %s "$WORK/new.rows")"
else
  echo "G1_BYTE_MISMATCH old vs new:"
  cmp "$WORK/old.rows" "$WORK/new.rows" | head -3
fi
python3 "$HERE/chi_rows.py" cmp "$WORK/old.rows" "$WORK/new.rows" \
  | tee "$WORK/cmp.log" || true
NDIFF=$(sed -n 's/^CMP rows=\([0-9]*\) diffs=\([0-9]*\).*/\2/p' "$WORK/cmp.log")
NROWS=$(sed -n 's/^CMP rows=\([0-9]*\).*/\1/p' "$WORK/cmp.log")
[ -n "$NROWS" ] && [ "$NROWS" -gt 1000 ] || fail "vacuous parity: only $NROWS rows compared"
[ "$NDIFF" = "0" ] || fail "$NDIFF of $NROWS rows differ from the pre-change binary"

echo "=== G1e: the forced rows equal the old path's single-pair histograms"
python3 - "$HERE" "$WORK/old.rows" "$WORK/new.rows" <<'EOF'
import sys
sys.path.insert(0, sys.argv[1])
from chi_rows import read_rows
old = read_rows(sys.argv[2])
new = read_rows(sys.argv[3])
n = min(len(old), len(new))
forced = 0
w1 = 0
sb = 0
bad = 0
for a, b in zip(old[:n], new[:n]):
    marked = b['flags'] & 16
    if b['width'] == 1 and not marked:
        forced += 1; w1 += 1
    elif len(b['pairs']) == 1 and not marked:
        forced += 1; sb += 1
    else:
        continue
    if not (a['width'] == b['width'] and a['eof'] == b['eof']
            and a['pairs'] == b['pairs']):
        bad += 1
print('G1_FORCED forced_rows=%d (width1=%d single_branch=%d) mismatches=%d'
      % (forced, w1, sb, bad))
assert forced > 0, 'vacuous: no forced rows in the set'
assert bad == 0, 'forced rows do not equal the old path\'s single-pair histograms'
print('G1_FORCED_OK forced_rows=%d all_equal_old=1' % forced)
EOF
[ $? -eq 0 ] || fail "forced rows mismatch"

echo "=== G1f: v4 decodes back to exactly the v3 rows"
python3 - "$HERE" "$WORK/new.rows" "$WORK/v4.rows" <<'EOF'
import sys
sys.path.insert(0, sys.argv[1])
from chi_rows import read_rows, read_rows_v4
v3 = read_rows(sys.argv[2])
v4 = read_rows_v4(sys.argv[3])
assert len(v3) == len(v4), 'v4 run lost rows: %d vs %d' % (len(v3), len(v4))
kinds = 0
diffs = 0
bytes_saved = 0
import os
bytes_saved = os.path.getsize(sys.argv[2]) - os.path.getsize(sys.argv[3])
for a, b in zip(v3, v4):
    if b.get('forced'):
        kinds += 1
        if not (a['flags'] & 16) and a['width'] > a['eof'] and \
           len(a['pairs']) == 1 and a['pairs'][0][1] == a['width'] - a['eof']:
            pass  # the compact form is exactly this row
    if (a['doc'], a['off'], a['width'], a['eof'], a['pairs'], a['flags'] & ~64,
            a['ctxlen'], a['docid'], a['base']) != \
       (b['doc'], b['off'], b['width'], b['eof'], b['pairs'], b['flags'] & ~64,
            b['ctxlen'], b['docid'], b['base']):
        diffs += 1
print('G1_V4 rows=%d forced_kind=%d diffs=%d bytes_saved=%d (%.1f%%)'
      % (len(v3), kinds, diffs, bytes_saved,
         100.0 * bytes_saved / max(1, os.path.getsize(sys.argv[2]))))
assert diffs == 0, 'v4 decode differs from the v3 rows'
print('G1_V4_OK forced_kind=%d identical=1' % kinds)
EOF
[ $? -eq 0 ] || fail "v4 decode mismatch"

echo "=== G1g: the layer receipts of the new run"
grep -E "CONSULT_SEPFRAMING|CHI_ZEROLOCATE" "$WORK/new.rows.journal" | tail -2
LAY=$(grep CONSULT_LAYERS "$WORK/new.rows.journal" | tail -1)
[ -n "$LAY" ] || fail "no CONSULT_LAYERS receipt"
echo "G1_LAYERS $LAY"

echo "=== G1 SUMMARY"
echo "G1_PARITY_OK rows_compared=$NROWS byte_identical=1 forced_equal_old=1 v4_forced_kind_ok=1"
